SELECT v.product_id, (SELECT name FROM products x WHERE x.product_id = v.product_id), SUM(oi.line_total_bdt) AS g FROM order_items oi JOIN product_variants v USING (variant_id) WHERE oi.order_id IN (SELECT order_id FROM orders o WHERE o.is_deleted = FALSE AND o.status IN ('delivered', 'in_transit', 'returned') AND o.order_at >= TIMESTAMP '2024-04-01 00:00:00' AND o.order_at < TIMESTAMP '2024-07-01 00:00:00') AND v.product_id IN (SELECT product_id FROM products WHERE name IN (SELECT name FROM products GROUP BY 1 HAVING COUNT(*) >= 2)) GROUP BY v.product_id ORDER BY g DESC, v.product_id LIMIT 5
